/* PetPolicyCheck · /veterans/ UI strings (EN|FR|ES|DE|KO|JA) from /workspace/traduction/5-pages-20261107/veterans.json, merged into PPC_I18N before ppc-i18n.js boots. 2026-11-07 */
(function(){var P=window.PPC_I18N=window.PPC_I18N||{strings:{}};var S=P.strings=P.strings||{};var C={"en":{"veterans.meta.title":"Veterans Service Dog & Pet Travel Hub (US & Canada) | PetPolicyCheck","veterans.meta.description":"DOT Part 382 vs Canada CTA service dog rules, ADA hotel rights, CR80 handler card, snowbird and VA lodging notes. Free — no donations.","veterans.hero.eyebrow":"Veterans · US &amp; Canada","veterans.hero.h1":"Service dogs &amp; veteran pet travel","veterans.hero.sub":"Free public utility for US and Canadian veterans. Zero donations. Institutional midnight-navy design for VA, Legion, DAV, VFW, and service-dog orgs to link.","veterans.switch.mode.aria":"Mode","veterans.switch.mode.sd":"Service Dog (PTSD / Mobility / Guide)","veterans.switch.mode.pet":"Companion Pet &amp; Relocation","veterans.switch.country.aria":"Country","veterans.switch.country.US":"United States","veterans.switch.country.CA":"Canada","veterans.switch.country.XB":"Cross-Border US ↔ Canada","veterans.air.US_sd.h2":"US air travel — 14 CFR Part 382","veterans.air.US_sd.p1":"Task-trained service dogs (including psychiatric/PTSD and mobility) may fly in cabin at <b>$0</b> under DOT rules. Pet weight limits are not the test for service dogs. The dog must fit safely on your lap or in your foot space without encroaching on another passenger. If it cannot, the carrier must consider the alternatives in 14 CFR 382.77. If your reservation was made more than 48 hours before the first originally scheduled departure, the airline may require the DOT form up to 48 hours in advance. If booked less than 48 hours before departure, it may require the form at the departure gate on travel day, but not advance notice. Contact the airline promptly; reasonable-effort accommodation rules also apply. For a flight segment scheduled to take eight hours or more, the airline may also require the DOT Service Animal Relief Attestation Form. Complete current DOT forms on or after the date you purchase your ticket.","veterans.air.US_sd.note":"<b>Note:</b> A universal 48-hour deadline is not the DOT rule: last-minute bookings have a departure-gate submission pathway, and reasonable-effort accommodation requirements apply. AMC service-animal paperwork follows separate rules.","veterans.air.US_sd.p2":"<b>Owner-trained</b> service dogs are accepted under US DOT when they meet the definition. ESAs are <b>not</b> service animals for airlines since 2021. Official resource: <a href=\"https://www.transportation.gov/\" rel=\"noopener\" target=\"_blank\">transportation.gov</a>.","veterans.air.CA_sd.h2":"Canada air travel — CTA / ATPDR trap","veterans.air.CA_sd.p1":"Canada’s transportation regulator is the Canadian Transportation Agency (CTA/OTC), not Air Canada. Under the ATPDR, carriers may request evidence of individual training by an organization or person specializing in service-dog training. ADI/IGDF accreditation is not a universal ATPDR requirement. Check your airline’s accepted documentation. US acceptance does not automatically establish eligibility on every non-US flight. Air Canada offers an assessment pathway for eligible owner-trained dogs through Cabin-Ready Canines; its June 2, 2026 announcement excludes travel to/from the United States, where US documentation rules apply. Confirm the process with Accessibility Services. Canada does not have one universal ADI-only rule for airline travel, hotel access and border entry. Check the applicable transport rule, carrier policy, provincial law and import category separately. Confirm: <a href=\"https://otc-cta.gc.ca/\" rel=\"noopener\" target=\"_blank\">otc-cta.gc.ca</a>.","veterans.air.XB_sd.h2":"Cross-border US ↔ Canada","veterans.air.XB_sd.p1":"Check the operating carrier and each flight. DOT Part 382 applies to US carriers and covered foreign-carrier flights to/from US airports; US codeshares may add responsibilities. Air Canada states that US documentation rules govern travel to/from the United States. Check Canadian requirements separately for other flights and for border entry. Canada does not have one universal ADI-only rule for airline travel, hotel access and border entry. Check the applicable transport rule, carrier policy, provincial law and import category separately.","veterans.air.US_pet.h2":"US companion pet flights","veterans.air.US_pet.p1":"Pets pay airline pet fees and must fit published carriers. Use <a href=\"../fit/\">Fit Check</a> and <a href=\"../airlines/compare/\">comparator</a>. Military PCS cargo exceptions: see <a href=\"../military-pcs/\">PCS kit</a>.","veterans.air.CA_pet.h2":"Canada companion pet flights","veterans.air.CA_pet.p1":"Confirm cabin dimensions (often soft-sided only) and CFIA entry pathway. Dogs imported for rescue, adoption, fostering or transfer to another person fall under commercial-import rules. An unaccompanied journey alone does not determine the category: establish ownership, the importer, age, origin and intended use using CFIA guidance.","veterans.air.XB_pet.h2":"Cross-border companion pets","veterans.air.XB_pet.p1":"CDC Dog Import Form into the US; CFIA personal vs commercial into Canada. Never assume a rescue handoff is “personal.”","veterans.hotel.US.h2":"US hotels — ADA Title III","veterans.hotel.US.p1":"Service dogs: <b>$0 pet fee</b>; breed/weight bans do not apply. Staff may ask only (1) whether the dog is a service animal required because of a disability, and (2) what work or task it is trained to perform. No medical documentation required. Handler remains responsible for control and damages.","veterans.hotel.CA.h2":"Canada hotels — provincial service dog / human rights laws","veterans.hotel.CA.p1":"Accredited/recognized service dogs are generally exempt from pet fees and pet bans under provincial frameworks. Policies vary by province — carry provincial ID/lettering if issued.","veterans.hotel.XB.h2":"Hotels on both sides of the border","veterans.hotel.XB.p1":"US ADA two-question rule + Canadian provincial service dog protections. Always clarify service dog vs pet at booking.","veterans.cardsec.h2":"Service Dog Handler Access Card (CR80)","veterans.cardsec.privacy":"100% local in your browser — zero medical or personal data ever transmitted or stored on our servers.","veterans.cardsec.label.handler":"Handler first name (optional)","veterans.cardsec.label.dog":"Dog name (optional)","veterans.cardsec.label.juri":"Jurisdiction","veterans.cardsec.opt.US":"US ADA + DOT","veterans.cardsec.opt.CA":"Canada CTA + Provincial","veterans.cardsec.opt.XB":"US ↔ Canada Cross-Border","veterans.cardsec.btn.generate":"Generate card","veterans.cardsec.btn.print":"Print","veterans.cardsec.btn.png":"Download PNG","veterans.cardsec.dotnote":"<b>Card back, full text:</b> DOT forms: check the airline’s submission process. Advance notice of up to 48 hours may apply to bookings made more than 48 hours before the first scheduled departure; last-minute bookings can submit forms at the departure gate.","veterans.snow.h2":"Veteran snowbirds &amp; VA / military lodging","veterans.snow.li1":"<b>Canada → US (snowbird):</b> CDC Dog Import Form receipt — often usable for months for dogs from dog-rabies-free/low-risk countries (confirm CDC). Keep rabies docs current.","veterans.snow.li2":"<b>Mexico:</b> SENASICA/OISA entry. Dogs entering or returning to the US from Mexico require screwworm-freedom certification based on inspection within five days before shipment. Mexico also requires a separate NWS inspection document for pet dogs originating in and travelling from the US, effective August 3, 2026. Check the required signatory and document for each direction.","veterans.snow.li3":"<b>Fisher House:</b> Fisher House is not ordinary pet-friendly lodging. For example, VA South Texas does not allow pets and requires prior approval for the registered guest’s task-trained service animal. Confirm eligibility and the specific house’s service-animal procedure before arrival.","veterans.snow.li4":"<b>Navy Lodge / IHG Army Hotels:</b> service dogs free. Companion-pet availability, room allocation, fees and size restrictions depend on the property. Navy Lodge asks guests to register pets and contact the lodge for multiple pets or pets over 70 lb. IHG Army Hotels asks guests to notify reservations and check its pet policy. A room booking does not grant base access.","veterans.snow.btn.pcs":"Military PCS kit","veterans.snow.btn.filter":"Military &amp; service dog filter","veterans.snow.btn.passport":"Passport","veterans.card.front.h4":"Service Dog Handler Card","veterans.card.front.handler":"Handler:","veterans.card.front.dog":"Dog:","veterans.card.q1":"Is the dog a service animal required because of a disability?","veterans.card.q2":"What work or task has the dog been trained to perform?","veterans.card.ada_title":"US ADA — only 2 questions staff may ask","veterans.card.fee":"<b>$0 pet fee</b> for task-trained service dogs (ADA Title III).","veterans.card.can":"<b>Canada</b> — check the applicable transport rule, the carrier’s service-dog policy and the provincial law before you travel.","veterans.card.lbl_us":"United States (ADA)","veterans.card.lbl_ca":"Canada","veterans.card.v15":"US ADA information only — not a service-dog certificate or proof of eligibility. This card does not replace airline forms, Canadian documentation or border-entry requirements. Check the law applicable to your destination.","veterans.card.back.h4":"Pre-flight checklist","veterans.card.back.dot":"DOT forms: follow the airline’s process. Up to 48 h notice may apply if booked >48 h ahead; last-minute bookings: at the gate.","veterans.card.back.relief8":"Flights of 8 h or more: the airline may also require the DOT Relief Attestation Form.","veterans.card.back.ca":"Canada: confirm the carrier’s accepted specialized-training evidence and any owner-trained assessment pathway. Border-import rules are separate.","veterans.card.back.gear":"Relief schedule · harness · “service dog” ID if you use one","veterans.card.png.title":"PetPolicyCheck · Service Dog Handler Card"},"fr":{"veterans.meta.title":"Espace vétérans : chiens d'assistance et voyages avec animaux (États-Unis et Canada) | PetPolicyCheck","veterans.meta.description":"Règles DOT Part 382 et règles canadiennes de l'OTC (CTA) pour les chiens d'assistance, droits ADA à l'hôtel, carte de maître-chien CR80, notes snowbirds et hébergement VA. Gratuit, sans dons.","veterans.hero.eyebrow":"Vétérans · États-Unis &amp; Canada","veterans.hero.h1":"Chiens d'assistance &amp; voyages des vétérans avec leurs animaux","veterans.hero.sub":"Service public gratuit pour les vétérans américains et canadiens. Aucun don. Design institutionnel bleu nuit, pensé pour que VA, Legion, DAV, VFW et les organisations de chiens d'assistance puissent y renvoyer.","veterans.switch.mode.aria":"Mode","veterans.switch.mode.sd":"Chien d'assistance (TSPT / mobilité / guide)","veterans.switch.mode.pet":"Animal de compagnie &amp; déménagement","veterans.switch.country.aria":"Pays","veterans.switch.country.US":"États-Unis","veterans.switch.country.CA":"Canada","veterans.switch.country.XB":"Transfrontalier États-Unis ↔ Canada","veterans.air.US_sd.h2":"Voyage aérien aux États-Unis — 14 CFR Part 382","veterans.air.US_sd.p1":"Les chiens d'assistance dressés à accomplir des tâches (y compris pour un handicap psychiatrique/TSPT ou de mobilité) peuvent voyager en cabine pour <b>$0</b> selon les règles du DOT. Les limites de poids applicables aux animaux de compagnie ne sont pas le critère pour les chiens d'assistance. Le chien doit tenir en sécurité sur vos genoux ou dans l'espace à vos pieds, sans empiéter sur un autre passager. Sinon, le transporteur doit examiner les solutions prévues au 14 CFR 382.77. Si votre réservation a été faite plus de 48 heures avant le premier départ initialement prévu, la compagnie peut exiger le formulaire DOT jusqu'à 48 heures à l'avance. Si vous avez réservé moins de 48 heures avant le départ, elle peut exiger le formulaire à la porte d'embarquement le jour du voyage, mais pas de préavis. Contactez rapidement la compagnie ; les règles d'« efforts raisonnables » d'accommodement s'appliquent aussi. Pour un segment de vol prévu de huit heures ou plus, la compagnie peut aussi exiger le DOT Service Animal Relief Attestation Form. Remplissez les formulaires DOT en vigueur à la date d'achat de votre billet ou après.","veterans.air.US_sd.note":"<b>Remarque :</b> un délai universel de 48 heures n'est pas la règle du DOT : pour les réservations de dernière minute, les formulaires peuvent être remis à la porte d'embarquement, et les exigences d'« efforts raisonnables » d'accommodement s'appliquent. Les documents AMC pour animaux d'assistance suivent des règles distinctes.","veterans.air.US_sd.p2":"Les chiens d'assistance <b>dressés par leur maître</b> sont acceptés par le DOT américain lorsqu'ils répondent à la définition. Depuis 2021, les animaux de soutien émotionnel (ESA) ne sont <b>pas</b> considérés comme des animaux d'assistance par les compagnies aériennes. Ressource officielle : <a href=\"https://www.transportation.gov/\" rel=\"noopener\" target=\"_blank\">transportation.gov</a>.","veterans.air.CA_sd.h2":"Voyage aérien au Canada — le piège OTC (CTA) / RTAPH (ATPDR)","veterans.air.CA_sd.p1":"Au Canada, l'autorité de réglementation des transports est l'Office des transports du Canada (OTC/CTA), et non Air Canada. En vertu du RTAPH (ATPDR), les transporteurs peuvent demander une preuve de dressage individuel par un organisme ou une personne spécialisés dans le dressage de chiens d'assistance. L'accréditation ADI/IGDF n'est pas une exigence universelle du RTAPH. Vérifiez les documents acceptés par votre compagnie. Une acceptation aux États-Unis ne vaut pas automatiquement admissibilité sur tous les vols hors États-Unis. Air Canada propose une procédure d'évaluation pour les chiens admissibles dressés par leur maître, via Cabin-Ready Canines ; son annonce du 2 juin 2026 exclut les vols à destination ou en provenance des États-Unis, où s'appliquent les règles américaines en matière de documents. Confirmez la démarche auprès des Services d'accessibilité. Le Canada n'a pas de règle unique « ADI seulement » valable à la fois pour l'avion, l'accès à l'hôtel et l'entrée à la frontière. Vérifiez séparément la règle de transport applicable, la politique du transporteur, la loi provinciale et la catégorie d'importation. À confirmer : <a href=\"https://otc-cta.gc.ca/\" rel=\"noopener\" target=\"_blank\">otc-cta.gc.ca</a>.","veterans.air.XB_sd.h2":"Transfrontalier États-Unis ↔ Canada","veterans.air.XB_sd.p1":"Vérifiez le transporteur exploitant et chaque vol. Le DOT Part 382 s'applique aux transporteurs américains et aux vols couverts de transporteurs étrangers à destination ou en provenance d'aéroports américains ; les partages de code américains peuvent ajouter des obligations. Air Canada indique que les règles américaines en matière de documents régissent les vols à destination ou en provenance des États-Unis. Vérifiez séparément les exigences canadiennes pour les autres vols et pour l'entrée à la frontière. Le Canada n'a pas de règle unique « ADI seulement » valable à la fois pour l'avion, l'accès à l'hôtel et l'entrée à la frontière. Vérifiez séparément la règle de transport applicable, la politique du transporteur, la loi provinciale et la catégorie d'importation.","veterans.air.US_pet.h2":"Vols avec animal de compagnie aux États-Unis","veterans.air.US_pet.p1":"Les animaux de compagnie paient les frais de la compagnie et doivent tenir dans les sacs/cages aux dimensions publiées. Utilisez le <a href=\"../fit/\">Fit Check</a> et le <a href=\"../airlines/compare/\">comparateur</a>. Exceptions cargo pour les PCS militaires : voir le <a href=\"../military-pcs/\">kit PCS</a>.","veterans.air.CA_pet.h2":"Vols avec animal de compagnie au Canada","veterans.air.CA_pet.p1":"Vérifiez les dimensions admises en cabine (souvent sacs souples uniquement) et la procédure d'entrée de l'ACIA (CFIA). Les chiens importés pour un sauvetage, une adoption, un placement en famille d'accueil ou un transfert à une autre personne relèvent des règles d'importation commerciale. Un voyage non accompagné ne détermine pas à lui seul la catégorie : établissez la propriété, l'importateur, l'âge, l'origine et l'usage prévu à l'aide des directives de l'ACIA.","veterans.air.XB_pet.h2":"Animaux de compagnie : trajets transfrontaliers","veterans.air.XB_pet.p1":"CDC Dog Import Form pour entrer aux États-Unis ; distinction personnel / commercial de l'ACIA (CFIA) pour entrer au Canada. Ne supposez jamais qu'une remise de chien de sauvetage est « personnelle ».","veterans.hotel.US.h2":"Hôtels aux États-Unis — ADA Title III","veterans.hotel.US.p1":"Chiens d'assistance : <b>$0 de frais pour animaux</b> ; les interdictions liées à la race ou au poids ne s'appliquent pas. Le personnel peut seulement demander (1) si le chien est un animal d'assistance requis en raison d'un handicap et (2) quel travail ou quelle tâche il a été dressé à accomplir. Aucun document médical n'est exigé. Le maître reste responsable du contrôle du chien et des dommages.","veterans.hotel.CA.h2":"Hôtels au Canada — lois provinciales sur les chiens d'assistance / droits de la personne","veterans.hotel.CA.p1":"Les chiens d'assistance accrédités ou reconnus sont généralement exemptés des frais et des interdictions visant les animaux de compagnie dans les cadres provinciaux. Les politiques varient selon la province : emportez la carte ou l'attestation provinciale si elle a été délivrée.","veterans.hotel.XB.h2":"Hôtels des deux côtés de la frontière","veterans.hotel.XB.p1":"Règle ADA des deux questions aux États-Unis + protections provinciales canadiennes pour les chiens d'assistance. Précisez toujours à la réservation s'il s'agit d'un chien d'assistance ou d'un animal de compagnie.","veterans.cardsec.h2":"Carte d'accès du maître-chien d'assistance (CR80)","veterans.cardsec.privacy":"100 % local dans votre navigateur : aucune donnée médicale ou personnelle n'est transmise ni stockée sur nos serveurs.","veterans.cardsec.label.handler":"Prénom du maître-chien (facultatif)","veterans.cardsec.label.dog":"Nom du chien (facultatif)","veterans.cardsec.label.juri":"Juridiction","veterans.cardsec.opt.US":"États-Unis : ADA + DOT","veterans.cardsec.opt.CA":"Canada : OTC (CTA) + provincial","veterans.cardsec.opt.XB":"Transfrontalier États-Unis ↔ Canada","veterans.cardsec.btn.generate":"Générer la carte","veterans.cardsec.btn.print":"Imprimer","veterans.cardsec.btn.png":"Télécharger le PNG","veterans.cardsec.dotnote":"<b>Verso de la carte, texte complet :</b> formulaires DOT : vérifiez la procédure de remise de la compagnie. Un préavis pouvant aller jusqu'à 48 heures peut s'appliquer aux réservations faites plus de 48 heures avant le premier départ prévu ; pour les réservations de dernière minute, les formulaires peuvent être remis à la porte d'embarquement.","veterans.snow.h2":"Vétérans « snowbirds » &amp; hébergement VA / militaire","veterans.snow.li1":"<b>Canada → États-Unis (snowbird) :</b> accusé de réception du CDC Dog Import Form — souvent utilisable pendant des mois pour les chiens venant de pays indemnes de rage canine ou à faible risque (à confirmer auprès du CDC). Gardez les documents antirabiques à jour.","veterans.snow.li2":"<b>Mexique :</b> entrée SENASICA/OISA. Les chiens qui entrent ou reviennent aux États-Unis depuis le Mexique doivent disposer d'une certification d'absence de lucilie bouchère (screwworm), fondée sur une inspection effectuée dans les cinq jours précédant l'expédition. Depuis le 3 août 2026, le Mexique exige aussi un document d'inspection NWS distinct pour les chiens de compagnie originaires des États-Unis et voyageant depuis ce pays. Vérifiez le signataire et le document exigés dans chaque sens.","veterans.snow.li3":"<b>Fisher House :</b> Fisher House n'est pas un hébergement ordinaire acceptant les animaux. Par exemple, VA South Texas n'accepte pas les animaux de compagnie et exige une autorisation préalable pour l'animal d'assistance dressé de l'hôte enregistré. Vérifiez l'admissibilité et la procédure de la maison concernée pour les animaux d'assistance avant votre arrivée.","veterans.snow.li4":"<b>Navy Lodge / IHG Army Hotels :</b> chiens d'assistance gratuits. La possibilité d'accueillir un animal de compagnie, l'attribution des chambres, les frais et les restrictions de taille dépendent de l'établissement. Navy Lodge demande d'enregistrer les animaux et de contacter l'établissement pour plusieurs animaux ou un animal de plus de 70 lb. IHG Army Hotels demande de prévenir le service des réservations et de consulter sa politique relative aux animaux. Une réservation de chambre ne donne pas accès à la base.","veterans.snow.btn.pcs":"Kit PCS militaire","veterans.snow.btn.filter":"Filtre militaires &amp; chiens d'assistance","veterans.snow.btn.passport":"Passport","veterans.card.front.h4":"Carte du maître-chien d'assistance","veterans.card.front.handler":"Maître-chien :","veterans.card.front.dog":"Chien :","veterans.card.q1":"Ce chien est-il un animal d'assistance requis en raison d'un handicap ?","veterans.card.q2":"Quel travail ou quelle tâche ce chien a-t-il été dressé à accomplir ?","veterans.card.ada_title":"ADA (États-Unis) — les 2 seules questions que le personnel peut poser","veterans.card.fee":"<b>$0 de frais pour animaux</b> pour les chiens d'assistance dressés à des tâches (ADA Title III).","veterans.card.can":"<b>Canada</b> — avant de voyager, vérifiez la règle de transport applicable, la politique du transporteur pour les chiens d'assistance et la loi provinciale.","veterans.card.lbl_us":"États-Unis (ADA)","veterans.card.lbl_ca":"Canada","veterans.card.v15":"Informations ADA (États-Unis) uniquement — ni certificat de chien d'assistance, ni preuve d'admissibilité. Cette carte ne remplace pas les formulaires des compagnies, les documents canadiens ni les exigences d'entrée à la frontière. Vérifiez la loi applicable à votre destination.","veterans.card.back.h4":"Check-list avant le vol","veterans.card.back.dot":"Formulaires DOT : suivez la procédure de la compagnie. Préavis jusqu'à 48 h possible si réservé >48 h avant ; réservations de dernière minute : à la porte.","veterans.card.back.relief8":"Vols de 8 h ou plus : la compagnie peut aussi exiger le DOT Relief Attestation Form.","veterans.card.back.ca":"Canada : vérifiez les preuves de dressage spécialisé acceptées par le transporteur et toute procédure d'évaluation pour les chiens dressés par leur maître. Les règles d'importation à la frontière sont distinctes.","veterans.card.back.gear":"Horaires de besoins · harnais · identifiant « chien d'assistance » si vous en utilisez un","veterans.card.png.title":"PetPolicyCheck · Carte du maître-chien d'assistance"},"es":{"veterans.meta.title":"Centro para veteranos: compañeros de servicio y viajes con mascotas (EE. UU. y Canadá) | PetPolicyCheck","veterans.meta.description":"Normas DOT Part 382 frente a las de la CTA de Canadá para compañeros de servicio, derechos ADA en hoteles, tarjeta de guía CR80, notas para snowbirds y alojamiento VA. Gratis, sin donaciones.","veterans.hero.eyebrow":"Veteranos · EE. UU. &amp; Canadá","veterans.hero.h1":"Compañeros de servicio &amp; viajes de veteranos con mascotas","veterans.hero.sub":"Servicio público gratuito para veteranos de EE. UU. y Canadá. Sin donaciones. Diseño institucional azul marino para que VA, Legion, DAV, VFW y las organizaciones de compañeros de servicio puedan enlazarlo.","veterans.switch.mode.aria":"Modo","veterans.switch.mode.sd":"Compañero de servicio (TEPT / movilidad / guía)","veterans.switch.mode.pet":"Mascota de compañía &amp; mudanza","veterans.switch.country.aria":"País","veterans.switch.country.US":"Estados Unidos","veterans.switch.country.CA":"Canadá","veterans.switch.country.XB":"Transfronterizo EE. UU. ↔ Canadá","veterans.air.US_sd.h2":"Viajes en avión en EE. UU. — 14 CFR Part 382","veterans.air.US_sd.p1":"Los perros de servicio entrenados para realizar tareas (incluidos los de discapacidad psiquiátrica/TEPT y de movilidad) pueden volar en cabina por <b>$0</b> según las normas del DOT. Los límites de peso para mascotas no son el criterio para los perros de servicio. El compañero debe caber de forma segura en su regazo o en el espacio para los pies sin invadir el de otro pasajero. Si no cabe, la aerolínea debe considerar las alternativas del 14 CFR 382.77. Si hizo la reserva más de 48 horas antes de la primera salida programada originalmente, la aerolínea puede exigir el formulario DOT hasta 48 horas antes. Si reservó menos de 48 horas antes de la salida, puede exigir el formulario en la puerta de embarque el día del viaje, pero no un aviso previo. Contacte pronto con la aerolínea; también se aplican las normas de esfuerzo razonable para la adaptación. Para un tramo de vuelo programado de ocho horas o más, la aerolínea también puede exigir el DOT Service Animal Relief Attestation Form. Complete los formularios DOT vigentes en la fecha de compra del boleto o después.","veterans.air.US_sd.note":"<b>Nota:</b> un plazo universal de 48 horas no es la norma del DOT: las reservas de última hora pueden entregar los formularios en la puerta de embarque y se aplican los requisitos de esfuerzo razonable para la adaptación. La documentación de AMC para animales de servicio sigue normas distintas.","veterans.air.US_sd.p2":"Los perros de servicio <b>entrenados por su dueño</b> se aceptan según el DOT de EE. UU. cuando cumplen la definición. Desde 2021, los animales de apoyo emocional (ESA) <b>no</b> son animales de servicio para las aerolíneas. Recurso oficial: <a href=\"https://www.transportation.gov/\" rel=\"noopener\" target=\"_blank\">transportation.gov</a>.","veterans.air.CA_sd.h2":"Viajes en avión en Canadá — la trampa CTA / ATPDR","veterans.air.CA_sd.p1":"El regulador de transporte de Canadá es la Canadian Transportation Agency (CTA/OTC), no Air Canada. Según el ATPDR, las aerolíneas pueden pedir pruebas del entrenamiento individual impartido por una organización o persona especializada en el entrenamiento de perros de servicio. La acreditación ADI/IGDF no es un requisito universal del ATPDR. Consulte la documentación que acepta su aerolínea. Ser aceptado en EE. UU. no garantiza automáticamente la elegibilidad en todos los vuelos fuera de EE. UU. Air Canada ofrece un procedimiento de evaluación para perros elegibles entrenados por su dueño a través de Cabin-Ready Canines; su anuncio del 2 de junio de 2026 excluye los viajes desde/hacia Estados Unidos, donde se aplican las normas estadounidenses de documentación. Confirme el proceso con Accessibility Services. Canadá no tiene una única norma universal de «solo ADI» para viajes en avión, acceso a hoteles y entrada en la frontera. Compruebe por separado la norma de transporte aplicable, la política de la aerolínea, la ley provincial y la categoría de importación. Confirme en: <a href=\"https://otc-cta.gc.ca/\" rel=\"noopener\" target=\"_blank\">otc-cta.gc.ca</a>.","veterans.air.XB_sd.h2":"Transfronterizo EE. UU. ↔ Canadá","veterans.air.XB_sd.p1":"Compruebe la aerolínea operadora y cada vuelo. El DOT Part 382 se aplica a las aerolíneas estadounidenses y a los vuelos cubiertos de aerolíneas extranjeras desde/hacia aeropuertos de EE. UU.; los códigos compartidos estadounidenses pueden añadir responsabilidades. Air Canada indica que las normas estadounidenses de documentación rigen los viajes desde/hacia Estados Unidos. Compruebe por separado los requisitos canadienses para otros vuelos y para la entrada en la frontera. Canadá no tiene una única norma universal de «solo ADI» para viajes en avión, acceso a hoteles y entrada en la frontera. Compruebe por separado la norma de transporte aplicable, la política de la aerolínea, la ley provincial y la categoría de importación.","veterans.air.US_pet.h2":"Vuelos con mascota de compañía en EE. UU.","veterans.air.US_pet.p1":"Las mascotas pagan las tarifas de la aerolínea y deben caber en transportadoras de las medidas publicadas. Use el <a href=\"../fit/\">Fit Check</a> y el <a href=\"../airlines/compare/\">comparador</a>. Excepciones de carga para PCS militares: consulte el <a href=\"../military-pcs/\">kit PCS</a>.","veterans.air.CA_pet.h2":"Vuelos con mascota de compañía en Canadá","veterans.air.CA_pet.p1":"Confirme las dimensiones admitidas en cabina (a menudo solo transportadoras blandas) y el procedimiento de entrada de la CFIA. Los perros importados para rescate, adopción, acogida o traspaso a otra persona se rigen por las normas de importación comercial. Viajar sin acompañante no determina por sí solo la categoría: establezca la propiedad, el importador, la edad, el origen y el uso previsto con la guía de la CFIA.","veterans.air.XB_pet.h2":"Mascotas de compañía: viajes transfronterizos","veterans.air.XB_pet.p1":"CDC Dog Import Form para entrar en EE. UU.; distinción personal / comercial de la CFIA para entrar en Canadá. Nunca dé por hecho que la entrega de un compañero rescatado es «personal».","veterans.hotel.US.h2":"Hoteles en EE. UU. — ADA Title III","veterans.hotel.US.p1":"Perros de servicio: <b>$0 de tarifa para mascotas</b>; no se aplican prohibiciones por raza o peso. El personal solo puede preguntar (1) si el perro es un animal de servicio necesario por una discapacidad y (2) qué trabajo o tarea ha sido entrenado para realizar. No se exige documentación médica. El guía sigue siendo responsable del control del compañero y de los daños.","veterans.hotel.CA.h2":"Hoteles en Canadá — leyes provinciales sobre perros de servicio / derechos humanos","veterans.hotel.CA.p1":"Los perros de servicio acreditados o reconocidos suelen estar exentos de las tarifas y prohibiciones para mascotas según los marcos provinciales. Las políticas varían según la provincia: lleve la identificación o el documento provincial si se lo han emitido.","veterans.hotel.XB.h2":"Hoteles a ambos lados de la frontera","veterans.hotel.XB.p1":"Regla ADA de las dos preguntas en EE. UU. + protecciones provinciales canadienses para perros de servicio. Aclare siempre al reservar si se trata de un compañero de servicio o de una mascota.","veterans.cardsec.h2":"Tarjeta de acceso para guías de compañeros de servicio (CR80)","veterans.cardsec.privacy":"100 % local en su navegador: ningún dato médico o personal se transmite ni se guarda en nuestros servidores.","veterans.cardsec.label.handler":"Nombre del guía (opcional)","veterans.cardsec.label.dog":"Nombre del compañero K9 (opcional)","veterans.cardsec.label.juri":"Jurisdicción","veterans.cardsec.opt.US":"EE. UU.: ADA + DOT","veterans.cardsec.opt.CA":"Canadá: CTA + provincial","veterans.cardsec.opt.XB":"Transfronterizo EE. UU. ↔ Canadá","veterans.cardsec.btn.generate":"Generar tarjeta","veterans.cardsec.btn.print":"Imprimir","veterans.cardsec.btn.png":"Descargar PNG","veterans.cardsec.dotnote":"<b>Reverso de la tarjeta, texto completo:</b> formularios DOT: consulte el procedimiento de entrega de la aerolínea. Puede aplicarse un aviso previo de hasta 48 horas a las reservas hechas más de 48 horas antes de la primera salida programada; en las reservas de última hora, los formularios pueden entregarse en la puerta de embarque.","veterans.snow.h2":"Veteranos «snowbirds» &amp; alojamiento VA / militar","veterans.snow.li1":"<b>Canadá → EE. UU. (snowbird):</b> comprobante del CDC Dog Import Form; a menudo sirve durante meses para perros de países libres de rabia canina o de bajo riesgo (confírmelo con el CDC). Mantenga al día la documentación antirrábica.","veterans.snow.li2":"<b>México:</b> entrada SENASICA/OISA. Los perros que entran o regresan a EE. UU. desde México necesitan una certificación de ausencia de gusano barrenador (screwworm) basada en una inspección realizada en los cinco días previos al envío. Desde el 3 de agosto de 2026, México también exige un documento de inspección NWS aparte para perros de compañía originarios de EE. UU. que viajan desde allí. Compruebe el firmante y el documento exigidos en cada sentido.","veterans.snow.li3":"<b>Fisher House:</b> Fisher House no es un alojamiento corriente que admita mascotas. Por ejemplo, VA South Texas no admite mascotas y exige aprobación previa para el animal de servicio entrenado del huésped registrado. Confirme la elegibilidad y el procedimiento de la casa concreta para animales de servicio antes de llegar.","veterans.snow.li4":"<b>Navy Lodge / IHG Army Hotels:</b> perros de servicio gratis. La admisión de mascotas, la asignación de habitaciones, las tarifas y las restricciones de tamaño dependen del establecimiento. Navy Lodge pide registrar las mascotas y contactar con el alojamiento si llevas varias o alguna de más de 70 lb. IHG Army Hotels pide avisar a reservas y consultar su política de mascotas. Reservar una habitación no da acceso a la base.","veterans.snow.btn.pcs":"Kit PCS militar","veterans.snow.btn.filter":"Filtro militares &amp; compañeros de servicio","veterans.snow.btn.passport":"Passport","veterans.card.front.h4":"Tarjeta del guía de compañero de servicio","veterans.card.front.handler":"Guía:","veterans.card.front.dog":"Compañero:","veterans.card.q1":"¿Es el perro un animal de servicio necesario por una discapacidad?","veterans.card.q2":"¿Qué trabajo o tarea ha sido entrenado para realizar el perro?","veterans.card.ada_title":"ADA (EE. UU.): las 2 únicas preguntas que puede hacer el personal","veterans.card.fee":"<b>$0 de tarifa para mascotas</b> para perros de servicio entrenados en tareas (ADA Title III).","veterans.card.can":"<b>Canadá</b>: antes de viajar, compruebe la norma de transporte aplicable, la política de la aerolínea sobre perros de servicio y la ley provincial.","veterans.card.lbl_us":"Estados Unidos (ADA)","veterans.card.lbl_ca":"Canadá","veterans.card.v15":"Solo información sobre la ADA de EE. UU.: no es un certificado de perro de servicio ni una prueba de elegibilidad. Esta tarjeta no sustituye los formularios de la aerolínea, la documentación canadiense ni los requisitos de entrada en la frontera. Compruebe la ley aplicable en su destino.","veterans.card.back.h4":"Lista de comprobación antes del vuelo","veterans.card.back.dot":"Formularios DOT: siga el proceso de la aerolínea. Aviso de hasta 48 h si reservó >48 h antes; reservas de última hora: en la puerta.","veterans.card.back.relief8":"Vuelos de 8 h o más: la aerolínea también puede exigir el DOT Relief Attestation Form.","veterans.card.back.ca":"Canadá: confirme qué pruebas de entrenamiento especializado acepta la aerolínea y si existe un procedimiento de evaluación para perros entrenados por su dueño. Las normas de importación en la frontera son aparte.","veterans.card.back.gear":"Horario para hacer sus necesidades · arnés · identificación de «perro de servicio» si la usa","veterans.card.png.title":"PetPolicyCheck · Tarjeta del guía de compañero de servicio","veterans.wall.h2":"Muro de Héroes","veterans.wall.intro":"Viajeros futuros y guías veteranos: envíe una foto de su <strong>compañero K9 de veterano</strong> y, tras la revisión de nuestro equipo, podrá aparecer aquí en PetPolicyCheck — un reconocimiento discreto a los compañeros que viajan con usted.","veterans.wall.submit.h3":"Enviar una foto","veterans.wall.rule1":"Envíe <strong>1 a 3 fotos</strong> del compañero solo, o de espalda — <strong>sin rostro humano</strong>.","veterans.wall.rule2":"<strong>Sin nombres de personas</strong>, y sin insignia militar, distintivo, rango, parche de unidad ni placa de vehículo en el encuadre.","veterans.wall.rule3":"Debe <strong>ser titular de los derechos</strong> de la(s) foto(s).","veterans.wall.rule4":"Cada foto es <strong>revisada por nuestro equipo</strong> antes de publicarse, y puede retirarse a petición.","veterans.wall.consent":"Consiento la publicación de la(s) foto(s) aprobada(s) únicamente en <strong>petpolicycheck.com</strong> (Muro de Héroes). Entiendo que las fotos se verifican antes de publicarse y que pueden retirarse a petición.","veterans.wall.mailto":"Envíe su foto por correo a contact@petpolicycheck.com","veterans.wall.note":"Abre su aplicación de correo con un mensaje listo. Adjunte la(s) foto(s) antes de enviar. No almacenamos cargas en este sitio estático.","veterans.wall.slot1.title":"Su compañero K9 podría estar aquí","veterans.wall.slot1.sub":"Sea el primer héroe","veterans.wall.slot2.title":"Su compañero K9 podría estar aquí","veterans.wall.slot2.sub":"Comparta una foto","veterans.wall.slot3.title":"Sea el primer héroe","veterans.wall.slot3.sub":"Compañeros de servicio bienvenidos","veterans.wall.slot4.title":"Su compañero K9 podría estar aquí","veterans.wall.slot4.sub":"Revisado antes de publicar","veterans.wall.slot5.title":"Honre a un compañero","veterans.wall.slot5.sub":"Solo el nombre del compañero","veterans.wall.empty.meta":"En espera de un envío verificado","veterans.wall.empty.aria":"Espacio vacío de la galería","veterans.wall.alt.default":"Compañero de servicio","veterans.wall.mailto.subject":"Muro de Héroes — envío de foto K9","veterans.wall.mailto.body":"Hola equipo de PetPolicyCheck,\n\nDeseo enviar una foto para el Muro de Héroes en petpolicycheck.com/veterans/.\n\nNombre del compañero: \nRol / unidad general (sin insignia, distintivo ni rango): \nAños de servicio (opcional): \nCiudad / país (opcional): \n\nConfirmo:\n- Soy titular de los derechos de la(s) foto(s).\n- 1 a 3 fotos adjuntas; el compañero solo o de espalda; sin rostro ni nombre humano; sin insignia militar, distintivo, rango ni placa de vehículo.\n- Consiento la publicación de la(s) foto(s) aprobada(s) únicamente en petpolicycheck.com (Muro de Héroes).\n- Entiendo que cada foto es revisada por su equipo antes de publicarse, y que puedo pedir su retirada en cualquier momento.\n\nGracias."},"de":{"veterans.meta.title":"Veteranen-Hub: Assistenzhunde und Reisen mit Haustier (USA & Kanada) | PetPolicyCheck","veterans.meta.description":"Assistenzhund-Regeln nach DOT Part 382 und kanadischer CTA, ADA-Rechte im Hotel, CR80-Halterkarte, Hinweise für Snowbirds und VA-Unterkünfte. Kostenlos – keine Spenden.","veterans.hero.eyebrow":"Veteranen · USA &amp; Kanada","veterans.hero.h1":"Assistenzhunde &amp; Reisen von Veteranen mit Haustier","veterans.hero.sub":"Kostenloses öffentliches Angebot für Veteranen aus den USA und Kanada. Keine Spenden. Institutionelles Design in Mitternachtsblau, damit VA, Legion, DAV, VFW und Assistenzhund-Organisationen darauf verlinken können.","veterans.switch.mode.aria":"Modus","veterans.switch.mode.sd":"Assistenzhund (PTBS / Mobilität / Blindenführhund)","veterans.switch.mode.pet":"Haustier &amp; Umzug","veterans.switch.country.aria":"Land","veterans.switch.country.US":"Vereinigte Staaten","veterans.switch.country.CA":"Kanada","veterans.switch.country.XB":"Grenzüberschreitend USA ↔ Kanada","veterans.air.US_sd.h2":"Flugreisen in den USA – 14 CFR Part 382","veterans.air.US_sd.p1":"Assistenzhunde, die für bestimmte Aufgaben ausgebildet sind (auch bei psychischer Behinderung/PTBS und Mobilitätseinschränkung), dürfen nach den DOT-Regeln für <b>$0</b> in der Kabine fliegen. Gewichtsgrenzen für Haustiere sind bei Assistenzhunden nicht der Maßstab. Der Hund muss sicher auf Ihrem Schoß oder im Fußraum Platz finden, ohne in den Bereich anderer Fluggäste hineinzuragen. Ist das nicht möglich, muss die Airline die Alternativen nach 14 CFR 382.77 prüfen. Wurde Ihre Buchung mehr als 48 Stunden vor dem ursprünglich geplanten ersten Abflug vorgenommen, kann die Airline das DOT-Formular bis zu 48 Stunden im Voraus verlangen. Bei Buchung weniger als 48 Stunden vor Abflug kann sie das Formular am Reisetag am Gate verlangen, aber keine Vorankündigung. Kontaktieren Sie die Airline frühzeitig; es gelten außerdem die Regeln über angemessene Bemühungen um Vorkehrungen. Für einen Flugabschnitt mit einer planmäßigen Dauer von acht Stunden oder mehr kann die Airline zusätzlich das DOT Service Animal Relief Attestation Form verlangen. Füllen Sie die aktuellen DOT-Formulare am Tag des Ticketkaufs oder danach aus.","veterans.air.US_sd.note":"<b>Hinweis:</b> Eine allgemeine 48-Stunden-Frist ist nicht die DOT-Regel: Bei Last-Minute-Buchungen können Formulare am Gate eingereicht werden, und es gelten die Anforderungen an angemessene Bemühungen um Vorkehrungen. Für AMC-Unterlagen zu Assistenztieren gelten eigene Regeln.","veterans.air.US_sd.p2":"<b>Vom Halter selbst ausgebildete</b> Assistenzhunde werden vom US-DOT akzeptiert, wenn sie die Definition erfüllen. Emotionale Unterstützungstiere (ESA) gelten seit 2021 für Airlines <b>nicht</b> als Assistenztiere. Offizielle Quelle: <a href=\"https://www.transportation.gov/\" rel=\"noopener\" target=\"_blank\">transportation.gov</a>.","veterans.air.CA_sd.h2":"Flugreisen in Kanada – die CTA-/ATPDR-Falle","veterans.air.CA_sd.p1":"Die kanadische Verkehrsaufsicht ist die Canadian Transportation Agency (CTA/OTC), nicht Air Canada. Nach den ATPDR können Airlines einen Nachweis über eine individuelle Ausbildung durch eine Organisation oder Person verlangen, die auf die Ausbildung von Assistenzhunden spezialisiert ist. Eine ADI-/IGDF-Akkreditierung ist keine allgemeine ATPDR-Voraussetzung. Prüfen Sie, welche Unterlagen Ihre Airline akzeptiert. Eine Anerkennung in den USA begründet nicht automatisch die Berechtigung auf jedem Flug außerhalb der USA. Air Canada bietet über Cabin-Ready Canines ein Prüfverfahren für berechtigte, vom Halter selbst ausgebildete Hunde an; laut Ankündigung vom 2. Juni 2026 gilt es nicht für Reisen in die oder aus den Vereinigten Staaten, für die die US-Dokumentationsregeln gelten. Klären Sie das Verfahren mit den Accessibility Services. In Kanada gibt es keine einheitliche „nur ADI“-Regel für Flugreisen, Hotelzugang und Grenzübertritt. Prüfen Sie die anwendbare Verkehrsregel, die Airline-Richtlinie, das Provinzrecht und die Einfuhrkategorie jeweils gesondert. Bestätigen: <a href=\"https://otc-cta.gc.ca/\" rel=\"noopener\" target=\"_blank\">otc-cta.gc.ca</a>.","veterans.air.XB_sd.h2":"Grenzüberschreitend USA ↔ Kanada","veterans.air.XB_sd.p1":"Prüfen Sie die ausführende Airline und jeden einzelnen Flug. DOT Part 382 gilt für US-Airlines und erfasste Flüge ausländischer Airlines von/zu US-Flughäfen; US-Codeshares können zusätzliche Pflichten mit sich bringen. Air Canada gibt an, dass für Reisen in die oder aus den Vereinigten Staaten die US-Dokumentationsregeln gelten. Prüfen Sie die kanadischen Anforderungen für andere Flüge und für den Grenzübertritt gesondert. In Kanada gibt es keine einheitliche „nur ADI“-Regel für Flugreisen, Hotelzugang und Grenzübertritt. Prüfen Sie die anwendbare Verkehrsregel, die Airline-Richtlinie, das Provinzrecht und die Einfuhrkategorie jeweils gesondert.","veterans.air.US_pet.h2":"Flüge mit Haustier in den USA","veterans.air.US_pet.p1":"Für Haustiere fallen die Tiergebühren der Airline an, und sie müssen in Transportboxen der veröffentlichten Maße passen. Nutzen Sie den <a href=\"../fit/\">Fit Check</a> und den <a href=\"../airlines/compare/\">Vergleich</a>. Frachtausnahmen bei militärischen PCS-Umzügen: siehe <a href=\"../military-pcs/\">PCS-Kit</a>.","veterans.air.CA_pet.h2":"Flüge mit Haustier in Kanada","veterans.air.CA_pet.p1":"Prüfen Sie die zulässigen Kabinenmaße (oft nur weiche Taschen) und das CFIA-Einreiseverfahren. Hunde, die zur Rettung, Adoption, Pflege oder Übergabe an eine andere Person eingeführt werden, fallen unter die Regeln für gewerbliche Einfuhren. Eine unbegleitete Reise allein bestimmt die Kategorie nicht: Klären Sie anhand der CFIA-Leitlinien Eigentum, Einführer, Alter, Herkunft und Verwendungszweck.","veterans.air.XB_pet.h2":"Grenzüberschreitende Reisen mit Haustier","veterans.air.XB_pet.p1":"CDC Dog Import Form für die Einreise in die USA; CFIA-Unterscheidung privat / gewerblich für die Einreise nach Kanada. Gehen Sie nie davon aus, dass die Übergabe eines Rettungshundes „privat“ ist.","veterans.hotel.US.h2":"Hotels in den USA – ADA Title III","veterans.hotel.US.p1":"Assistenzhunde: <b>$0 Tiergebühr</b>; Rasse- oder Gewichtsverbote gelten nicht. Das Personal darf nur fragen, (1) ob der Hund ein wegen einer Behinderung benötigtes Assistenztier ist und (2) für welche Arbeit oder Aufgabe er ausgebildet ist. Medizinische Unterlagen sind nicht erforderlich. Der Halter bleibt für die Kontrolle des Hundes und für Schäden verantwortlich.","veterans.hotel.CA.h2":"Hotels in Kanada – Provinzgesetze zu Assistenzhunden / Menschenrechten","veterans.hotel.CA.p1":"Akkreditierte bzw. anerkannte Assistenzhunde sind nach den Regelungen der Provinzen in der Regel von Tiergebühren und Haustierverboten befreit. Die Regeln unterscheiden sich je nach Provinz – führen Sie einen Provinzausweis bzw. eine Bescheinigung mit, falls ausgestellt.","veterans.hotel.XB.h2":"Hotels auf beiden Seiten der Grenze","veterans.hotel.XB.p1":"US-ADA-Regel der zwei Fragen + Schutz für Assistenzhunde nach kanadischem Provinzrecht. Klären Sie bei der Buchung immer, ob es sich um einen Assistenzhund oder ein Haustier handelt.","veterans.cardsec.h2":"Zugangskarte für Assistenzhund-Halter (CR80)","veterans.cardsec.privacy":"100 % lokal in Ihrem Browser – keinerlei medizinische oder persönliche Daten werden an unsere Server übertragen oder dort gespeichert.","veterans.cardsec.label.handler":"Vorname des Halters (optional)","veterans.cardsec.label.dog":"Name des Hundes (optional)","veterans.cardsec.label.juri":"Rechtsraum","veterans.cardsec.opt.US":"USA: ADA + DOT","veterans.cardsec.opt.CA":"Kanada: CTA + Provinz","veterans.cardsec.opt.XB":"Grenzüberschreitend USA ↔ Kanada","veterans.cardsec.btn.generate":"Karte erstellen","veterans.cardsec.btn.print":"Drucken","veterans.cardsec.btn.png":"PNG herunterladen","veterans.cardsec.dotnote":"<b>Kartenrückseite, vollständiger Text:</b> DOT-Formulare: Prüfen Sie das Einreichungsverfahren der Airline. Bei Buchungen mehr als 48 Stunden vor dem ersten planmäßigen Abflug kann eine Vorankündigung von bis zu 48 Stunden gelten; bei Last-Minute-Buchungen können die Formulare am Gate eingereicht werden.","veterans.snow.h2":"Veteranen als Snowbirds &amp; VA-/Militärunterkünfte","veterans.snow.li1":"<b>Kanada → USA (Snowbird):</b> Bestätigung des CDC Dog Import Form – für Hunde aus Ländern ohne bzw. mit geringem Hundetollwutrisiko oft monatelang nutzbar (beim CDC bestätigen). Halten Sie die Tollwutunterlagen aktuell.","veterans.snow.li2":"<b>Mexiko:</b> Einreise über SENASICA/OISA. Hunde, die aus Mexiko in die USA einreisen oder zurückkehren, benötigen eine Bescheinigung über die Freiheit von Schraubenwurmfliegen (Screwworm) auf Grundlage einer Untersuchung innerhalb von fünf Tagen vor dem Versand. Seit dem 3. August 2026 verlangt Mexiko außerdem ein separates NWS-Inspektionsdokument für Haushunde, die aus den USA stammen und von dort reisen. Prüfen Sie für jede Richtung, wer unterschreiben muss und welches Dokument nötig ist.","veterans.snow.li3":"<b>Fisher House:</b> Fisher House ist keine gewöhnliche haustierfreundliche Unterkunft. VA South Texas etwa erlaubt keine Haustiere und verlangt für das ausgebildete Assistenztier des registrierten Gastes eine vorherige Genehmigung. Klären Sie vor der Ankunft die Berechtigung und das Verfahren des jeweiligen Hauses für Assistenztiere.","veterans.snow.li4":"<b>Navy Lodge / IHG Army Hotels:</b> Assistenzhunde kostenlos. Ob Haustiere erlaubt sind, die Zimmerzuteilung, Gebühren und Größenbeschränkungen hängen von der jeweiligen Unterkunft ab. Navy Lodge bittet, Haustiere anzumelden und sich bei mehreren Tieren oder Tieren über 70 lb an die Unterkunft zu wenden. IHG Army Hotels bittet, die Reservierung zu informieren und die eigene Haustierrichtlinie zu prüfen. Eine Zimmerbuchung berechtigt nicht zum Zutritt zum Stützpunkt.","veterans.snow.btn.pcs":"Militär-PCS-Kit","veterans.snow.btn.filter":"Filter Militär &amp; Assistenzhunde","veterans.snow.btn.passport":"Passport","veterans.card.front.h4":"Assistenzhund-Halterkarte","veterans.card.front.handler":"Halter:","veterans.card.front.dog":"Hund:","veterans.card.q1":"Ist der Hund ein wegen einer Behinderung benötigtes Assistenztier?","veterans.card.q2":"Für welche Arbeit oder Aufgabe wurde der Hund ausgebildet?","veterans.card.ada_title":"US-ADA – nur 2 Fragen darf das Personal stellen","veterans.card.fee":"<b>$0 Tiergebühr</b> für aufgabenbezogen ausgebildete Assistenzhunde (ADA Title III).","veterans.card.can":"<b>Kanada</b> – prüfen Sie vor der Reise die anwendbare Verkehrsregel, die Assistenzhund-Richtlinie der Airline und das Provinzrecht.","veterans.card.lbl_us":"Vereinigte Staaten (ADA)","veterans.card.lbl_ca":"Kanada","veterans.card.v15":"Nur Informationen zum US-ADA – kein Assistenzhund-Zertifikat und kein Nachweis einer Berechtigung. Diese Karte ersetzt weder Airline-Formulare noch kanadische Unterlagen oder Einreisebestimmungen. Prüfen Sie das am Zielort geltende Recht.","veterans.card.back.h4":"Checkliste vor dem Flug","veterans.card.back.dot":"DOT-Formulare: Verfahren der Airline befolgen. Bis zu 48 h Vorankündigung möglich bei Buchung >48 h vorher; Last-Minute-Buchungen: am Gate.","veterans.card.back.relief8":"Flüge ab 8 h: Die Airline kann zusätzlich das DOT Relief Attestation Form verlangen.","veterans.card.back.ca":"Kanada: Klären Sie, welche Nachweise einer Fachausbildung die Airline akzeptiert und ob es ein Prüfverfahren für selbst ausgebildete Hunde gibt. Die Einfuhrregeln an der Grenze gelten gesondert.","veterans.card.back.gear":"Plan für Gassi-Pausen · Geschirr · „Assistenzhund“-Kennzeichnung, falls Sie eine verwenden","veterans.card.png.title":"PetPolicyCheck · Assistenzhund-Halterkarte"},"ko":{"veterans.meta.title":"재향군인 서비스견·반려동물 여행 허브 (미국·캐나다) | PetPolicyCheck","veterans.meta.description":"DOT Part 382와 캐나다 CTA의 서비스견 규정 비교, ADA 호텔 권리, CR80 핸들러 카드, 스노버드 및 VA 숙소 안내. 무료 — 기부 없음.","veterans.hero.eyebrow":"재향군인 · 미국 &amp; 캐나다","veterans.hero.h1":"서비스견 &amp; 재향군인 반려동물 여행","veterans.hero.sub":"미국·캐나다 재향군인을 위한 무료 공공 도구입니다. 기부를 받지 않습니다. VA, Legion, DAV, VFW 및 서비스견 단체가 링크할 수 있도록 공공기관 스타일의 미드나이트 네이비 디자인을 적용했습니다.","veterans.switch.mode.aria":"모드","veterans.switch.mode.sd":"서비스견 (PTSD / 이동 보조 / 안내견)","veterans.switch.mode.pet":"반려동물 &amp; 이주","veterans.switch.country.aria":"국가","veterans.switch.country.US":"미국","veterans.switch.country.CA":"캐나다","veterans.switch.country.XB":"미국 ↔ 캐나다 국경 간 이동","veterans.air.US_sd.h2":"미국 항공 여행 — 14 CFR Part 382","veterans.air.US_sd.p1":"과제 수행 훈련을 받은 서비스견(정신장애/PTSD 및 이동 보조 포함)은 DOT 규정에 따라 <b>$0</b>로 기내에 탑승할 수 있습니다. 반려동물 무게 제한은 서비스견의 기준이 아닙니다. 개는 다른 승객의 공간을 침범하지 않고 보호자의 무릎 위나 발밑 공간에 안전하게 있을 수 있어야 합니다. 그럴 수 없다면 항공사는 14 CFR 382.77에 따른 대안을 검토해야 합니다. 최초 예정 출발 시각보다 48시간 이상 전에 예약했다면, 항공사는 최대 48시간 전까지 DOT 양식 제출을 요구할 수 있습니다. 출발 48시간 이내에 예약했다면 여행 당일 탑승구에서 양식을 요구할 수는 있지만 사전 통보를 요구할 수는 없습니다. 항공사에 신속히 연락하세요. 합리적 노력에 따른 편의 제공 규정도 적용됩니다. 예정 비행시간이 8시간 이상인 구간에서는 DOT Service Animal Relief Attestation Form을 추가로 요구할 수 있습니다. 현행 DOT 양식은 항공권 구매일 또는 그 이후에 작성하세요.","veterans.air.US_sd.note":"<b>참고:</b> 일률적인 48시간 기한은 DOT 규정이 아닙니다. 임박 예약은 탑승구에서 제출할 수 있는 경로가 있으며, 합리적 노력에 따른 편의 제공 요건이 적용됩니다. AMC 서비스 동물 서류는 별도 규정을 따릅니다.","veterans.air.US_sd.p2":"<b>보호자가 직접 훈련한</b> 서비스견도 정의를 충족하면 미국 DOT 기준으로 인정됩니다. 정서 지원 동물(ESA)은 2021년부터 항공사에서 서비스 동물로 인정되지 <b>않습니다</b>. 공식 자료: <a href=\"https://www.transportation.gov/\" rel=\"noopener\" target=\"_blank\">transportation.gov</a>.","veterans.air.CA_sd.h2":"캐나다 항공 여행 — CTA / ATPDR 함정","veterans.air.CA_sd.p1":"캐나다의 교통 규제 기관은 Air Canada가 아니라 캐나다 교통청(CTA/OTC)입니다. ATPDR에 따라 항공사는 서비스견 훈련을 전문으로 하는 기관 또는 개인이 개별 훈련을 했다는 증빙을 요청할 수 있습니다. ADI/IGDF 인증은 ATPDR의 일률적인 요건이 아닙니다. 이용 항공사가 인정하는 서류를 확인하세요. 미국에서 인정받았다고 해서 미국 외 모든 항공편에서 자동으로 자격이 인정되는 것은 아닙니다. Air Canada는 Cabin-Ready Canines를 통해 보호자가 직접 훈련한 적격 견을 위한 평가 절차를 운영합니다. 2026년 6월 2일 발표에 따르면 미국 출도착 여행은 제외되며, 이 경우 미국 서류 규정이 적용됩니다. 절차는 Accessibility Services에 확인하세요. 캐나다에는 항공 여행, 호텔 이용, 국경 입국 모두에 적용되는 단일한 'ADI 전용' 규정이 없습니다. 적용되는 교통 규정, 항공사 정책, 주(州) 법, 수입 분류를 각각 확인하세요. 확인: <a href=\"https://otc-cta.gc.ca/\" rel=\"noopener\" target=\"_blank\">otc-cta.gc.ca</a>.","veterans.air.XB_sd.h2":"미국 ↔ 캐나다 국경 간 이동","veterans.air.XB_sd.p1":"운항 항공사와 각 항공편을 확인하세요. DOT Part 382는 미국 항공사와, 미국 공항 출도착 외국 항공사 항공편 중 적용 대상에 적용되며, 미국 공동운항(코드셰어)은 추가 책임을 부과할 수 있습니다. Air Canada는 미국 출도착 여행에는 미국 서류 규정이 적용된다고 밝히고 있습니다. 그 밖의 항공편과 국경 입국에 대한 캐나다 요건은 따로 확인하세요. 캐나다에는 항공 여행, 호텔 이용, 국경 입국 모두에 적용되는 단일한 'ADI 전용' 규정이 없습니다. 적용되는 교통 규정, 항공사 정책, 주(州) 법, 수입 분류를 각각 확인하세요.","veterans.air.US_pet.h2":"미국 반려동물 항공편","veterans.air.US_pet.p1":"반려동물은 항공사 반려동물 요금을 내야 하며 공시된 규격의 이동장에 들어가야 합니다. <a href=\"../fit/\">Fit Check</a>와 <a href=\"../airlines/compare/\">비교 도구</a>를 이용하세요. 군 PCS 화물 예외: <a href=\"../military-pcs/\">PCS 키트</a>를 참고하세요.","veterans.air.CA_pet.h2":"캐나다 반려동물 항공편","veterans.air.CA_pet.p1":"기내 반입 규격(대개 소프트 케이스만 가능)과 CFIA 입국 절차를 확인하세요. 구조, 입양, 임시 보호 또는 타인에게 양도할 목적으로 수입되는 개는 상업용 수입 규정을 따릅니다. 보호자 비동반 여부만으로 분류가 정해지지는 않습니다. CFIA 지침에 따라 소유권, 수입자, 나이, 출발지, 이용 목적을 확인하세요.","veterans.air.XB_pet.h2":"국경 간 반려동물 이동","veterans.air.XB_pet.p1":"미국 입국은 CDC Dog Import Form, 캐나다 입국은 CFIA의 개인용·상업용 구분을 따릅니다. 구조견 인계를 '개인용'이라고 단정하지 마세요.","veterans.hotel.US.h2":"미국 호텔 — ADA Title III","veterans.hotel.US.p1":"서비스견: <b>반려동물 요금 $0</b>, 견종·무게 제한은 적용되지 않습니다. 직원은 (1) 장애 때문에 필요한 서비스 동물인지, (2) 어떤 작업이나 과제를 수행하도록 훈련받았는지만 물을 수 있습니다. 의료 서류는 요구되지 않습니다. 개의 통제와 손해에 대한 책임은 핸들러에게 있습니다.","veterans.hotel.CA.h2":"캐나다 호텔 — 주(州) 서비스견·인권 법","veterans.hotel.CA.p1":"인증·인정된 서비스견은 주(州) 제도에 따라 대체로 반려동물 요금과 반려동물 금지 규정에서 면제됩니다. 정책은 주마다 다르므로, 주에서 발급한 신분증이나 증명서가 있다면 지참하세요.","veterans.hotel.XB.h2":"국경 양쪽의 호텔","veterans.hotel.XB.p1":"미국 ADA의 '두 가지 질문' 규정 + 캐나다 주(州)의 서비스견 보호 규정. 예약할 때 서비스견인지 반려동물인지 항상 분명히 밝히세요.","veterans.cardsec.h2":"서비스견 핸들러 출입 카드 (CR80)","veterans.cardsec.privacy":"100% 브라우저 안에서만 처리됩니다. 의료 정보나 개인 정보는 저희 서버로 전송되거나 저장되지 않습니다.","veterans.cardsec.label.handler":"핸들러 이름 (선택)","veterans.cardsec.label.dog":"개 이름 (선택)","veterans.cardsec.label.juri":"관할","veterans.cardsec.opt.US":"미국 ADA + DOT","veterans.cardsec.opt.CA":"캐나다 CTA + 주(州) 규정","veterans.cardsec.opt.XB":"미국 ↔ 캐나다 국경 간","veterans.cardsec.btn.generate":"카드 만들기","veterans.cardsec.btn.print":"인쇄","veterans.cardsec.btn.png":"PNG 다운로드","veterans.cardsec.dotnote":"<b>카드 뒷면 전체 문구:</b> DOT 양식: 항공사의 제출 절차를 확인하세요. 첫 예정 출발 48시간 이상 전에 한 예약에는 최대 48시간 전 사전 통보가 적용될 수 있으며, 임박 예약은 탑승구에서 양식을 제출할 수 있습니다.","veterans.snow.h2":"재향군인 스노버드 &amp; VA / 군 숙소","veterans.snow.li1":"<b>캐나다 → 미국 (스노버드):</b> CDC Dog Import Form 접수 확인서 — 개 광견병 청정국·저위험국에서 오는 개는 여러 달 동안 사용할 수 있는 경우가 많습니다(CDC에서 확인). 광견병 서류를 최신 상태로 유지하세요.","veterans.snow.li2":"<b>멕시코:</b> SENASICA/OISA 입국. 멕시코에서 미국으로 입국하거나 돌아가는 개는 선적 전 5일 이내 검사에 근거한 나선구더기(screwworm) 비감염 증명이 필요합니다. 멕시코는 2026년 8월 3일부터 미국에서 태어나 미국에서 출발하는 반려견에 대해 별도의 NWS 검사 서류도 요구합니다. 방향별로 필요한 서명권자와 서류를 확인하세요.","veterans.snow.li3":"<b>Fisher House:</b> Fisher House는 일반적인 반려동물 동반 숙소가 아닙니다. 예를 들어 VA South Texas는 반려동물을 허용하지 않으며, 등록된 투숙객의 과제 수행 훈련을 받은 서비스 동물에 대해 사전 승인을 요구합니다. 도착 전에 자격과 해당 하우스의 서비스 동물 절차를 확인하세요.","veterans.snow.li4":"<b>Navy Lodge / IHG Army Hotels:</b> 서비스견은 무료입니다. 반려동물 동반 가능 여부, 객실 배정, 요금, 크기 제한은 숙소마다 다릅니다. Navy Lodge는 반려동물 등록을 요청하며, 여러 마리이거나 70 lb를 넘는 경우 숙소에 문의하라고 안내합니다. IHG Army Hotels는 예약 부서에 미리 알리고 반려동물 정책을 확인하라고 안내합니다. 객실을 예약해도 기지 출입 권한이 생기지는 않습니다.","veterans.snow.btn.pcs":"군 PCS 키트","veterans.snow.btn.filter":"군인 &amp; 서비스견 필터","veterans.snow.btn.passport":"Passport","veterans.card.front.h4":"서비스견 핸들러 카드","veterans.card.front.handler":"핸들러:","veterans.card.front.dog":"개:","veterans.card.q1":"이 개는 장애 때문에 필요한 서비스 동물입니까?","veterans.card.q2":"이 개는 어떤 작업이나 과제를 수행하도록 훈련받았습니까?","veterans.card.ada_title":"미국 ADA — 직원이 물을 수 있는 질문은 2가지뿐","veterans.card.fee":"과제 수행 훈련을 받은 서비스견은 <b>반려동물 요금 $0</b> (ADA Title III).","veterans.card.can":"<b>캐나다</b> — 여행 전에 적용되는 교통 규정, 항공사의 서비스견 정책, 주(州) 법을 확인하세요.","veterans.card.lbl_us":"미국 (ADA)","veterans.card.lbl_ca":"캐나다","veterans.card.v15":"미국 ADA 안내일 뿐이며, 서비스견 증명서나 자격 증빙이 아닙니다. 이 카드는 항공사 양식, 캐나다 서류, 국경 입국 요건을 대신하지 않습니다. 목적지에 적용되는 법을 확인하세요.","veterans.card.back.h4":"탑승 전 체크리스트","veterans.card.back.dot":"DOT 양식: 항공사 절차를 따르세요. >48 h 전 예약 시 최대 48 h 사전 통보가 필요할 수 있음. 임박 예약: 탑승구에서 제출.","veterans.card.back.relief8":"8 h 이상 비행: 항공사가 DOT Relief Attestation Form을 추가로 요구할 수 있음.","veterans.card.back.ca":"캐나다: 항공사가 인정하는 전문 훈련 증빙과, 보호자가 직접 훈련한 개를 위한 평가 절차가 있는지 확인하세요. 국경 수입 규정은 별도입니다.","veterans.card.back.gear":"배변 일정 · 하네스 · 사용하는 경우 '서비스견' 표식","veterans.card.png.title":"PetPolicyCheck · 서비스견 핸들러 카드"},"ja":{"veterans.meta.title":"退役軍人向けサービスドッグ・ペット旅行ハブ（米国・カナダ） | PetPolicyCheck","veterans.meta.description":"DOT Part 382とカナダCTAのサービスドッグ規則、ADAのホテルでの権利、CR80ハンドラーカード、スノーバード・VA宿泊施設の注意点。無料・寄付不要。","veterans.hero.eyebrow":"退役軍人・米国 &amp; カナダ","veterans.hero.h1":"サービスドッグ &amp; 退役軍人のペット旅行","veterans.hero.sub":"米国・カナダの退役軍人向け無料公共ツール。寄付は一切受け付けません。VA、Legion、DAV、VFW、サービスドッグ団体がリンクしやすい、公的機関風のミッドナイトネイビーのデザインです。","veterans.switch.mode.aria":"モード","veterans.switch.mode.sd":"サービスドッグ（PTSD／移動介助／盲導犬）","veterans.switch.mode.pet":"ペット &amp; 転居","veterans.switch.country.aria":"国","veterans.switch.country.US":"米国","veterans.switch.country.CA":"カナダ","veterans.switch.country.XB":"米国 ↔ カナダ越境","veterans.air.US_sd.h2":"米国の空の旅 — 14 CFR Part 382","veterans.air.US_sd.p1":"作業・タスクの訓練を受けたサービスドッグ（精神障害／PTSDや移動介助を含む）は、DOTの規則に基づき<b>$0</b>で客室に同乗できます。ペットの重量制限はサービスドッグの判断基準ではありません。犬は、他の乗客のスペースにはみ出すことなく、膝の上または足元に安全に収まらなければなりません。収まらない場合、航空会社は14 CFR 382.77に定める代替措置を検討しなければなりません。当初予定の最初の出発時刻の48時間より前に予約した場合、航空会社は最大48時間前までのDOT書式の提出を求めることができます。出発前48時間を切ってから予約した場合は、旅行当日に搭乗口で書式を求めることはできますが、事前通知を求めることはできません。早めに航空会社へご連絡ください。合理的な努力による配慮に関する規則も適用されます。予定飛行時間が8時間以上の区間では、DOT Service Animal Relief Attestation Formも求められる場合があります。現行のDOT書式は、航空券の購入日以降にご記入ください。","veterans.air.US_sd.note":"<b>注：</b>一律の48時間期限はDOTの規則ではありません。直前の予約には搭乗口で提出する方法があり、合理的な努力による配慮の要件が適用されます。AMCのサービスアニマル書類は別の規則に従います。","veterans.air.US_sd.p2":"<b>飼い主が自ら訓練した</b>サービスドッグも、定義を満たせば米国DOTのもとで認められます。情緒支援動物（ESA）は2021年以降、航空会社ではサービスアニマルとして扱われ<b>ません</b>。公式情報：<a href=\"https://www.transportation.gov/\" rel=\"noopener\" target=\"_blank\">transportation.gov</a>。","veterans.air.CA_sd.h2":"カナダの空の旅 — CTA／ATPDRの落とし穴","veterans.air.CA_sd.p1":"カナダの運輸規制機関はAir Canadaではなく、カナダ運輸庁（CTA/OTC）です。ATPDRのもとでは、航空会社はサービスドッグ訓練を専門とする団体または個人による個別訓練の証明を求めることができます。ADI/IGDF認定はATPDRの一律の要件ではありません。利用航空会社が認める書類をご確認ください。米国で認められても、米国外のすべての便で自動的に資格が認められるわけではありません。Air CanadaはCabin-Ready Caninesを通じて、飼い主が訓練した適格な犬のための評価手続きを設けています。2026年6月2日の発表では米国発着の旅行は対象外で、その場合は米国の書類規則が適用されます。手続きはAccessibility Servicesにご確認ください。カナダには、空の旅、ホテル利用、国境での入国のすべてに適用される一律の「ADIのみ」の規則はありません。適用される運輸規則、航空会社の方針、州法、輸入区分をそれぞれご確認ください。確認先：<a href=\"https://otc-cta.gc.ca/\" rel=\"noopener\" target=\"_blank\">otc-cta.gc.ca</a>。","veterans.air.XB_sd.h2":"米国 ↔ カナダ越境","veterans.air.XB_sd.p1":"運航航空会社と各便をご確認ください。DOT Part 382は、米国の航空会社と、米国の空港を発着する外国航空会社の対象便に適用され、米国のコードシェアによって責任が加わる場合があります。Air Canadaは、米国発着の旅行には米国の書類規則が適用されるとしています。その他の便と国境での入国については、カナダの要件を別途ご確認ください。カナダには、空の旅、ホテル利用、国境での入国のすべてに適用される一律の「ADIのみ」の規則はありません。適用される運輸規則、航空会社の方針、州法、輸入区分をそれぞれご確認ください。","veterans.air.US_pet.h2":"米国のペット同伴フライト","veterans.air.US_pet.p1":"ペットには航空会社のペット料金がかかり、公表サイズのキャリーに収まる必要があります。<a href=\"../fit/\">Fit Check</a>と<a href=\"../airlines/compare/\">比較ツール</a>をご利用ください。軍のPCSにおける貨物の例外：<a href=\"../military-pcs/\">PCSキット</a>をご参照ください。","veterans.air.CA_pet.h2":"カナダのペット同伴フライト","veterans.air.CA_pet.p1":"客室持ち込みのサイズ（多くはソフトキャリーのみ）とCFIAの入国手続きをご確認ください。保護、譲渡、一時預かり、または他人への引き渡しを目的に輸入される犬は、商業輸入の規則の対象となります。非同伴の移動であることだけでは区分は決まりません。CFIAのガイダンスに沿って、所有者、輸入者、年齢、出発地、使用目的をご確認ください。","veterans.air.XB_pet.h2":"越境するペット","veterans.air.XB_pet.p1":"米国への入国にはCDC Dog Import Form、カナダへの入国にはCFIAの個人／商業の区分が関わります。保護犬の引き渡しを「個人」扱いだと決めつけてはなりません。","veterans.hotel.US.h2":"米国のホテル — ADA Title III","veterans.hotel.US.p1":"サービスドッグ：<b>ペット料金$0</b>。犬種・体重による制限は適用されません。スタッフが尋ねてよいのは、(1) 障害のために必要なサービスアニマルかどうか、(2) どのような作業・タスクの訓練を受けているか、の2点のみです。医療書類は不要です。犬の管理と損害の責任はハンドラーにあります。","veterans.hotel.CA.h2":"カナダのホテル — 州のサービスドッグ法／人権法","veterans.hotel.CA.p1":"認定・公認されたサービスドッグは、州の制度のもとで、ペット料金やペット禁止規定の対象外となるのが一般的です。方針は州によって異なるため、州発行のIDや証明書があれば携帯してください。","veterans.hotel.XB.h2":"国境の両側のホテル","veterans.hotel.XB.p1":"米国ADAの「2つの質問」ルール＋カナダ各州のサービスドッグ保護。予約時には、サービスドッグかペットかを必ず明確に伝えてください。","veterans.cardsec.h2":"サービスドッグ・ハンドラー アクセスカード（CR80）","veterans.cardsec.privacy":"100%ブラウザ内で処理されます。医療情報や個人情報がサーバーに送信・保存されることは一切ありません。","veterans.cardsec.label.handler":"ハンドラーの名（任意）","veterans.cardsec.label.dog":"犬の名前（任意）","veterans.cardsec.label.juri":"適用法域","veterans.cardsec.opt.US":"米国 ADA＋DOT","veterans.cardsec.opt.CA":"カナダ CTA＋州","veterans.cardsec.opt.XB":"米国 ↔ カナダ越境","veterans.cardsec.btn.generate":"カードを作成","veterans.cardsec.btn.print":"印刷","veterans.cardsec.btn.png":"PNGをダウンロード","veterans.cardsec.dotnote":"<b>カード裏面の全文：</b>DOT書式：航空会社の提出手続きをご確認ください。最初の予定出発の48時間より前に行った予約には、最大48時間前の事前通知が適用される場合があります。直前の予約では、搭乗口で書式を提出できます。","veterans.snow.h2":"退役軍人のスノーバード &amp; VA／軍の宿泊施設","veterans.snow.li1":"<b>カナダ → 米国（スノーバード）：</b>CDC Dog Import Formの受付確認。犬狂犬病の清浄国・低リスク国からの犬なら、数か月間使えることが多い（CDCでご確認ください）。狂犬病関連の書類は常に有効な状態にしておいてください。","veterans.snow.li2":"<b>メキシコ：</b>SENASICA／OISAによる入国。メキシコから米国に入国・帰国する犬には、出荷前5日以内の検査に基づくラセンウジバエ（screwworm）非感染証明が必要です。メキシコは2026年8月3日から、米国原産で米国から渡航するペットの犬に対し、別途NWS検査書類も求めています。方向ごとに、必要な署名者と書類をご確認ください。","veterans.snow.li3":"<b>Fisher House：</b>Fisher Houseは一般的なペット可の宿泊施設ではありません。例えばVA South Texasはペット不可で、登録宿泊者のタスク訓練を受けたサービスアニマルには事前承認が必要です。到着前に、利用資格と各ハウスのサービスアニマル手続きをご確認ください。","veterans.snow.li4":"<b>Navy Lodge／IHG Army Hotels：</b>サービスドッグは無料。ペットの受け入れ可否、部屋の割り当て、料金、サイズ制限は施設によって異なります。Navy Lodgeはペットの登録を求めており、複数頭または70 lbを超えるペットの場合は施設に連絡するよう案内しています。IHG Army Hotelsは予約窓口への事前連絡とペットポリシーの確認を求めています。客室を予約しても基地への立ち入りは認められません。","veterans.snow.btn.pcs":"軍PCSキット","veterans.snow.btn.filter":"軍関係者 &amp; サービスドッグ フィルター","veterans.snow.btn.passport":"Passport","veterans.card.front.h4":"サービスドッグ・ハンドラーカード","veterans.card.front.handler":"ハンドラー：","veterans.card.front.dog":"犬：","veterans.card.q1":"この犬は、障害のために必要なサービスアニマルですか？","veterans.card.q2":"この犬はどのような作業・タスクを行うよう訓練されていますか？","veterans.card.ada_title":"米国ADA — スタッフが尋ねてよいのは2つの質問のみ","veterans.card.fee":"タスク訓練を受けたサービスドッグは<b>ペット料金$0</b>（ADA Title III）。","veterans.card.can":"<b>カナダ</b> — 渡航前に、適用される運輸規則、航空会社のサービスドッグ方針、州法をご確認ください。","veterans.card.lbl_us":"米国（ADA）","veterans.card.lbl_ca":"カナダ","veterans.card.v15":"米国ADAに関する情報にすぎず、サービスドッグの証明書や資格の証明ではありません。このカードは航空会社の書式、カナダの書類、国境での入国要件の代わりにはなりません。渡航先で適用される法律をご確認ください。","veterans.card.back.h4":"搭乗前チェックリスト","veterans.card.back.dot":"DOT書式：航空会社の手続きに従ってください。>48 h前の予約は最大48 hの事前通知が必要な場合あり。直前予約：搭乗口で提出。","veterans.card.back.relief8":"8 h以上のフライト：航空会社がDOT Relief Attestation Formも求める場合あり。","veterans.card.back.ca":"カナダ：航空会社が認める専門訓練の証明と、飼い主が訓練した犬向けの評価手続きの有無をご確認ください。国境での輸入規則は別扱いです。","veterans.card.back.gear":"排泄のスケジュール・ハーネス・使用している場合は「サービスドッグ」の表示","veterans.card.png.title":"PetPolicyCheck・サービスドッグ・ハンドラーカード"},"it":{"veterans.meta.title":"Centro veterani: cani di servizio e viaggi con animali (USA e Canada) | PetPolicyCheck","veterans.meta.description":"Regole DOT Part 382 e CTA canadese per i cani di servizio, diritti ADA in hotel, tessera CR80 per il conduttore, note per snowbird e alloggi VA. Gratuito, senza donazioni.","veterans.hero.eyebrow":"Veterani · Stati Uniti e Canada","veterans.hero.h1":"Cani di servizio e viaggi con animali per i veterani","veterans.hero.sub":"Strumento pubblico gratuito per i veterani statunitensi e canadesi. Nessuna donazione. Impaginazione istituzionale blu notte, pensata per i link di VA, Legion, DAV, VFW e associazioni di cani di servizio.","veterans.switch.mode.aria":"Modalità","veterans.switch.mode.sd":"Cane di servizio (PTSD / mobilità / guida)","veterans.switch.mode.pet":"Animale da compagnia e trasferimento","veterans.switch.country.aria":"Paese","veterans.switch.country.US":"Stati Uniti","veterans.switch.country.CA":"Canada","veterans.switch.country.XB":"Transfrontaliero USA ↔ Canada","veterans.air.US_sd.h2":"Viaggi aerei negli Stati Uniti — 14 CFR Part 382","veterans.air.US_sd.p1":"I cani di servizio addestrati a un compito (compresi quelli per PTSD/psichiatrici e per la mobilità) possono volare in cabina a <b>0 $</b> secondo le regole DOT. I limiti di peso previsti per gli animali da compagnia non sono il criterio per i cani di servizio. Il cane deve stare in sicurezza in grembo o nello spazio ai Suoi piedi, senza invadere un altro passeggero. Se non è possibile, il vettore deve considerare le alternative di cui al 14 CFR 382.77. Se la prenotazione è stata fatta più di 48 ore prima della prima partenza originariamente prevista, la compagnia può richiedere il modulo DOT fino a 48 ore prima. Se ha prenotato a meno di 48 ore dalla partenza, può richiedere il modulo all’uscita d’imbarco il giorno del viaggio, ma non un preavviso. Contatti tempestivamente la compagnia; si applicano anche le regole sull’accomodamento ragionevole. Per un segmento di volo previsto di otto ore o più, la compagnia può richiedere anche il DOT Service Animal Relief Attestation Form. Compili i moduli DOT in vigore a partire dalla data di acquisto del biglietto.","veterans.air.US_sd.note":"<b>Nota:</b> un termine universale di 48 ore non è la regola DOT: le prenotazioni last minute hanno una via di presentazione all’uscita d’imbarco e si applicano gli obblighi di accomodamento ragionevole. I documenti AMC per i cani di servizio seguono regole distinte.","veterans.air.US_sd.p2":"I cani di servizio <b>addestrati dal proprietario</b> sono accettati secondo le regole DOT degli Stati Uniti se soddisfano la definizione. Gli ESA <b>non</b> sono animali di servizio per le compagnie aeree dal 2021. Fonte ufficiale: <a href=\"https://www.transportation.gov/\" rel=\"noopener\" target=\"_blank\">transportation.gov</a>.","veterans.air.CA_sd.h2":"Viaggi aerei in Canada — trappola CTA / ATPDR","veterans.air.CA_sd.p1":"L’autorità canadese dei trasporti è la Canadian Transportation Agency (CTA/OTC), non Air Canada. In base all’ATPDR, i vettori possono chiedere la prova di un addestramento individuale da parte di un’organizzazione o di una persona specializzata nell’addestramento dei cani di servizio. L’accreditamento ADI/IGDF non è un requisito ATPDR universale. Verifichi i documenti accettati dalla Sua compagnia. L’accettazione negli Stati Uniti non basta, di per sé, a stabilire l’idoneità su ogni volo extra-USA. Air Canada offre un percorso di valutazione per i cani addestrati dal proprietario aventi diritto tramite Cabin-Ready Canines; l’annuncio del 2 giugno 2026 esclude i viaggi da/verso gli Stati Uniti, dove valgono le regole documentali statunitensi. Confermi la procedura con Accessibility Services. Il Canada non ha un’unica regola universale «solo ADI» per il volo, l’accesso in hotel e l’ingresso alla frontiera. Verifichi separatamente la norma di trasporto applicabile, la policy del vettore, la legge provinciale e la categoria di importazione. Confermi su: <a href=\"https://otc-cta.gc.ca/\" rel=\"noopener\" target=\"_blank\">otc-cta.gc.ca</a>.","veterans.air.XB_sd.h2":"Transfrontaliero USA ↔ Canada","veterans.air.XB_sd.p1":"Verifichi il vettore operatore e ogni volo. La Part 382 DOT si applica ai vettori statunitensi e ai voli di vettori esteri coperti da/verso aeroporti USA; i codeshare statunitensi possono aggiungere responsabilità. Air Canada indica che le regole documentali statunitensi disciplinano i viaggi da/verso gli Stati Uniti. Verifichi a parte i requisiti canadesi per gli altri voli e per l’ingresso alla frontiera. Il Canada non ha un’unica regola universale «solo ADI» per il volo, l’accesso in hotel e l’ingresso alla frontiera. Verifichi separatamente la norma di trasporto applicabile, la policy del vettore, la legge provinciale e la categoria di importazione.","veterans.air.US_pet.h2":"Voli negli Stati Uniti con animale da compagnia","veterans.air.US_pet.p1":"Gli animali da compagnia pagano le tariffe della compagnia e devono entrare nei trasportini pubblicati. Usi la <a href=\"../fit/\">verifica della misura</a> e il <a href=\"../airlines/compare/\">comparatore</a>. Eccezioni cargo per i PCS militari: veda il <a href=\"../military-pcs/\">kit PCS</a>.","veterans.air.CA_pet.h2":"Voli in Canada con animale da compagnia","veterans.air.CA_pet.p1":"Confermi le dimensioni in cabina (spesso solo trasportini a pareti morbide) e il percorso di ingresso CFIA. I cani importati per soccorso, adozione, affidamento o cessione a un’altra persona rientrano nelle regole di importazione commerciale. Un viaggio non accompagnato, da solo, non determina la categoria: accerti proprietà, importatore, età, origine e uso previsto secondo le indicazioni della CFIA.","veterans.air.XB_pet.h2":"Animali da compagnia transfrontalieri","veterans.air.XB_pet.p1":"CDC Dog Import Form in ingresso negli Stati Uniti; CFIA personale o commerciale in ingresso in Canada. Non dia mai per scontato che il passaggio a un’associazione di soccorso sia «personale».","veterans.hotel.US.h2":"Hotel negli Stati Uniti — ADA Title III","veterans.hotel.US.p1":"Cani di servizio: <b>supplemento animali 0 $</b>; i divieti di razza o di peso non si applicano. Il personale può chiedere soltanto (1) se il cane è un animale di servizio richiesto a causa di una disabilità, e (2) quale lavoro o compito è addestrato a svolgere. Non è richiesta documentazione medica. Il conduttore resta responsabile del controllo e degli eventuali danni.","veterans.hotel.CA.h2":"Hotel in Canada — leggi provinciali sui cani di servizio / diritti della persona","veterans.hotel.CA.p1":"I cani di servizio accreditati o riconosciuti sono in genere esentati dai supplementi e dai divieti per animali, secondo i quadri provinciali. Le policy variano da una provincia all’altra: porti con sé l’eventuale documento o contrassegno provinciale.","veterans.hotel.XB.h2":"Hotel da una parte e dall’altra della frontiera","veterans.hotel.XB.p1":"Regola ADA statunitense delle due domande + tutele provinciali canadesi per i cani di servizio. Chiarisca sempre, in prenotazione, se si tratta di un cane di servizio o di un animale da compagnia.","veterans.cardsec.h2":"Tessera di accesso del conduttore di cane di servizio (CR80)","veterans.cardsec.privacy":"Tutto resta nel Suo browser: nessun dato medico o personale viene mai trasmesso o conservato sui nostri server.","veterans.cardsec.label.handler":"Nome del conduttore (facoltativo)","veterans.cardsec.label.dog":"Nome del cane (facoltativo)","veterans.cardsec.label.juri":"Giurisdizione","veterans.cardsec.opt.US":"ADA + DOT (Stati Uniti)","veterans.cardsec.opt.CA":"CTA + normativa provinciale (Canada)","veterans.cardsec.opt.XB":"Transfrontaliero USA ↔ Canada","veterans.cardsec.btn.generate":"Genera la tessera","veterans.cardsec.btn.print":"Stampa","veterans.cardsec.btn.png":"Scarica il PNG","veterans.cardsec.dotnote":"<b>Retro della tessera, testo integrale:</b> moduli DOT: segua la procedura di invio della compagnia. Un preavviso fino a 48 ore può applicarsi alle prenotazioni fatte più di 48 ore prima della prima partenza prevista; le prenotazioni last minute possono presentare i moduli all’uscita d’imbarco.","veterans.snow.h2":"Snowbird veterani e alloggi VA / militari","veterans.snow.li1":"<b>Canada → Stati Uniti (snowbird):</b> ricevuta del CDC Dog Import Form — spesso utilizzabile per mesi per i cani provenienti da Paesi privi di rabbia canina o a basso rischio (confermi presso i CDC). Tenga aggiornati i documenti antirabbici.","veterans.snow.li2":"<b>Messico:</b> ingresso SENASICA/OISA. I cani che entrano o rientrano negli Stati Uniti dal Messico richiedono una certificazione di assenza del verme della vite del Nuovo Mondo (screwworm) basata su un’ispezione nei cinque giorni precedenti la spedizione. Il Messico richiede anche un documento di ispezione NWS distinto per i cani da compagnia originari degli Stati Uniti e in partenza da lì, in vigore dal 3 agosto 2026. Verifichi firmatario e documento richiesti in ciascuna direzione.","veterans.snow.li3":"<b>Fisher House:</b> Fisher House non è un alloggio pet-friendly ordinario. Ad esempio, il VA South Texas non ammette gli animali da compagnia e richiede un’autorizzazione preventiva per l’animale di servizio addestrato a un compito dell’ospite registrato. Confermi l’idoneità e la procedura della singola struttura per gli animali di servizio prima dell’arrivo.","veterans.snow.li4":"<b>Navy Lodge / IHG Army Hotels:</b> cani di servizio gratuiti. Disponibilità, assegnazione delle camere, tariffe e limiti di taglia per gli animali da compagnia dipendono dalla struttura. Navy Lodge chiede di registrare gli animali e di contattare la lodge in caso di più animali o di animali oltre 70 lb. IHG Army Hotels chiede di avvisare il servizio prenotazioni e di consultare la propria policy. Una prenotazione della camera non dà accesso alla base.","veterans.snow.btn.pcs":"Kit PCS militare","veterans.snow.btn.filter":"Filtro militare e cani di servizio","veterans.snow.btn.passport":"Passport","veterans.card.front.h4":"Tessera del conduttore di cane di servizio","veterans.card.front.handler":"Conduttore:","veterans.card.front.dog":"Cane:","veterans.card.q1":"Il cane è un animale di servizio richiesto a causa di una disabilità?","veterans.card.q2":"Quale lavoro o compito il cane è addestrato a svolgere?","veterans.card.ada_title":"ADA statunitense — le uniche 2 domande che il personale può fare","veterans.card.fee":"<b>Supplemento animali 0 $</b> per i cani di servizio addestrati a un compito (ADA Title III).","veterans.card.can":"<b>Canada</b> — verifichi la norma di trasporto applicabile, la policy del vettore sui cani di servizio e la legge provinciale prima di viaggiare.","veterans.card.lbl_us":"Stati Uniti (ADA)","veterans.card.lbl_ca":"Canada","veterans.card.v15":"Solo informazioni sull’ADA statunitense: non è un certificato di cane di servizio né una prova di idoneità. Questa tessera non sostituisce i moduli delle compagnie, i documenti canadesi o i requisiti di ingresso alla frontiera. Verifichi la legge applicabile alla Sua destinazione.","veterans.card.back.h4":"Lista di controllo prima del volo","veterans.card.back.dot":"Moduli DOT: segua la procedura della compagnia. Un preavviso fino a 48 ore può applicarsi se ha prenotato con più di 48 ore di anticipo; prenotazioni last minute: all’uscita d’imbarco.","veterans.card.back.relief8":"Voli di 8 ore o più: la compagnia può richiedere anche il DOT Relief Attestation Form.","veterans.card.back.ca":"Canada: confermi le prove di addestramento specializzato accettate dal vettore e l’eventuale percorso di valutazione per i cani addestrati dal proprietario. Le regole di importazione alla frontiera sono distinte.","veterans.card.back.gear":"Orari per i bisogni · pettorina · eventuale riconoscimento «service dog» se lo usa","veterans.card.png.title":"PetPolicyCheck · Tessera del conduttore di cane di servizio","veterans.wall.h2":"Muro degli eroi","veterans.wall.intro":"Viaggiatori futuri e conduttori veterani: invii una foto del Suo <strong>compagno K9 o cane di servizio di un veterano</strong> e, dopo la verifica del nostro team, potrà comparire qui su PetPolicyCheck — un albo discreto per i compagni che viaggiano con Lei.","veterans.wall.submit.h3":"Inviare una foto","veterans.wall.rule1":"Invii <strong>da 1 a 3 foto</strong> del compagno da solo, o di spalle — <strong>senza viso umano</strong>.","veterans.wall.rule2":"<strong>Niente nomi di persone</strong> e, nell’inquadratura, niente insegne militari, distintivi, gradi, toppe di unità o targhe.","veterans.wall.rule3":"Deve <strong>essere titolare dei diritti</strong> della o delle foto.","veterans.wall.rule4":"Ogni foto è <strong>esaminata dal nostro team</strong> prima della pubblicazione e può essere ritirata su richiesta.","veterans.wall.consent":"Acconsento alla pubblicazione della o delle foto approvate unicamente su <strong>petpolicycheck.com</strong> (Muro degli eroi). Comprendo che le foto sono verificate prima di andare in linea e possono essere ritirate su richiesta.","veterans.wall.mailto":"Invii la foto a contact@petpolicycheck.com","veterans.wall.note":"Apre la Sua applicazione di posta con un messaggio già pronto. Allega la o le foto prima di inviare. Su questo sito statico non conserviamo caricamenti.","veterans.wall.slot1.title":"Il Suo compagno K9 potrebbe essere qui","veterans.wall.slot1.sub":"Sia il primo eroe","veterans.wall.slot2.title":"Il Suo compagno K9 potrebbe essere qui","veterans.wall.slot2.sub":"Condivida una foto","veterans.wall.slot3.title":"Sia il primo eroe","veterans.wall.slot3.sub":"I compagni di servizio sono i benvenuti","veterans.wall.slot4.title":"Il Suo compagno K9 potrebbe essere qui","veterans.wall.slot4.sub":"Esaminato prima della pubblicazione","veterans.wall.slot5.title":"Renda onore a un compagno","veterans.wall.slot5.sub":"Solo il nome del compagno","veterans.wall.empty.meta":"In attesa di un invio verificato","veterans.wall.empty.aria":"Spazio vuoto della galleria","veterans.wall.alt.default":"Compagno di servizio","veterans.wall.mailto.subject":"Muro degli eroi — invio di una foto K9","veterans.wall.mailto.body":"Buongiorno, team di PetPolicyCheck,\n\nDesidero inviare una foto per il Muro degli eroi su petpolicycheck.com/veterans/. Allego la o le foto e confermo di essere titolare dei diritti e di acconsentire alla pubblicazione sul solo petpolicycheck.com, dopo la verifica del Vostro team.\n\nGrazie."}};for(var l in C){S[l]=S[l]||{};for(var k in C[l])S[l][k]=C[l][k];}if(!window.PPC_T){window.PPC_T=function(k,en){var L=window.PPC_LANG,v=L&&L.t?L.t(k):null;if(v==null){var e=(window.PPC_I18N.strings.en||{})[k];v=e!=null?e:null}return v==null?en:v};window.addEventListener('ppc:lang',function(){document.querySelectorAll('meta[data-i18n-content]').forEach(function(m){var v=window.PPC_T(m.getAttribute('data-i18n-content'),null);if(v!=null){var x=document.createElement('textarea');x.innerHTML=v;m.setAttribute('content',x.value)}})})}})();
